/**
 * Waypoint type → marker glyph.
 *
 * The guide map draws each waypoint as a white badge with a category-coloured
 * ring (see GuideMap) and one of these ink glyphs on top, FarOut-style, so a
 * marker is identifiable without reading its label.
 *
 * The glyphs are committed PNGs (`assets/map-icons/`, generated by
 * `scripts/build-map-icons.mjs` from `@lib/map-glyphs`) rather than an icon font
 * or emoji: the map has to work fully offline, and the bundled glyph pbfs cover
 * Latin + punctuation only — no pictographs — so a symbol layer `textField`
 * cannot draw iconography.
 *
 * The mapping itself is `@lib/waypoint-glyphs`, shared with the web so a type
 * draws with the same glyph (and ring colour) on both. A POI and a waypoint of
 * the same kind look the same; the POI markers are told apart by the smaller,
 * thinner-ringed badge GuideMap draws underneath, not by the ink.
 *
 * The image registry lives next door in `waypoint-icon-images.ts`.
 */

import { MAP_GLYPH_NAMES, type MapGlyphName } from '@lib/map-glyphs';
import { FALLBACK_GLYPH, poiGlyph, waypointGlyph } from '@lib/waypoint-glyphs';

/** The shipped glyph set. Each name maps 1:1 to `assets/map-icons/<name>.png`. */
export const WAYPOINT_ICON_NAMES = MAP_GLYPH_NAMES;

export type WaypointIconName = MapGlyphName;

/** Glyph used for any type the shared table does not list (and for `poi` itself). */
export const FALLBACK_WAYPOINT_ICON: WaypointIconName = FALLBACK_GLYPH;

/** The glyph for a waypoint type (generic point-of-interest for unknowns). */
export function waypointIconName(type: string): WaypointIconName {
  return waypointGlyph(type);
}

/** The glyph for an OpenStreetMap POI category (fallback for an unknown one). */
export function poiIconName(category: string): WaypointIconName {
  return poiGlyph(category);
}
